inflight = {}
def get(key):
  if cache.has(key): return cache.stream(key)
  if key in inflight: return inflight[key].subscribe()
  f = inflight[key] = upstream.fetch_async(key, timeout=2s)
  f.on_complete(lambda body: (cache.put(key, body, ttl_for(key)), inflight.pop(key)))
  f.on_error(lambda e: (inflight.pop(key), negative_cache(key, 1s) if e.is_404 else None))
  return f.subscribe()

def nextRendition(buffer_s, tput_kbps):
  if buffer_s < 5: return lowest_rung_below(tput_kbps * 0.5)
  if buffer_s > 20: return highest_rung_below(tput_kbps * 0.9)
  return highest_rung_below(tput_kbps * 0.7)

def onSegmentResult(cdn, ok, dl_time, seg_dur):
  if not ok or dl_time > 1.5 * seg_dur: cdn.strikes += 1
  if cdn.strikes >= 2: switch_base_url(fallback)

def plan(cluster, forecast):
  items = sorted(forecast[cluster], key=lambda t: t.hours / t.bytes, reverse=True)
  budget = cluster.storage * 0.8
  plan = []
  for t in items:
    for r in t.renditions_for(cluster.device_mix):
      if budget >= r.bytes and not cluster.has(r): plan.append(r); budget -= r.bytes
  return schedule(plan, window=('02:00','08:00'), max_gbps=cluster.fill_link * 0.7)
